ON DUPLICATE KEY UPDATE country = VALUES(country), category = VALUES(category), organization = VALUES(organization), contact_info = VALUES(contact_info), source_url = VALUES(source_url), verified_on = VALUES(verified_on);

ON DUPLICATE KEY UPDATE title = VALUES(title), prompt_text = VALUES(prompt_text), option_a = VALUES(option_a), option_b = VALUES(option_b), correct_option = VALUES(correct_option), feedback_text = VALUES(feedback_text);
