INSERT INTO sandbox_scenarios (id, title, prompt_text, option_a, option_b, correct_option, feedback_text) VALUES
(1, 'The job offer that moves too fast', 'A WhatsApp message promises high pay for a remote job. The sender says there are only two places left and asks for a photo of your national ID through an unfamiliar link.', 'Send the ID photo so the offer doesn’t expire.', 'Pause and look up the employer’s official contact details independently.', 'B', 'An unexpected request for identification plus a short deadline is a warning sign. Verify the job through a channel you find yourself before sharing any details.'),
(2, 'The account threatening to share photos', 'An unknown social media account threatens to send private or edited photos to your contacts unless you pay today.', 'Save the messages if it is safe, get support, and use the platform’s reporting tools.', 'Pay now and trust the account to stop contacting you.', 'A', 'Payment gives you no control over what the sender does next. If it is safe to do so, keep copies, ask someone you trust for support, and follow official reporting guidance.'),
(3, 'The unexpected banking alert', 'An SMS claims your account will be locked and asks you to use a link to enter your one-time password.', 'Use the SMS link while the one-time password is still valid.', 'Open the bank’s usual app or use a number you already trust to check your account.', 'B', 'An OTP can authorize a payment or login. Use your normal banking app or a trusted contact number to check whether the warning is genuine.'),
(4, 'A friend with a new account', 'An account with your friend’s photo says they lost access to their usual profile and need you to transfer money immediately.', 'Contact your friend through a number or account you already know.', 'Send a small amount first to see if the request is real.', 'A', 'Profile photos and names are easy to copy. Checking with the person through a separate channel gives you a better way to confirm who is asking.')
